        mpy     x1,x0,a
        move    a,y1
        move    x0,a
        move    #>$2aaaab,y0
        mac     -y1,y0,a
; DC-free feedback: subtract a leaky mean (2^-10, ~7 Hz)
        move    x:(r7+$26),b
        move    x:(r7+$28),b0
        sub     b,a
        move    a,x:(r7+$21)
        asr     #$a,a,a
        add     a,b
        move    b1,x:(r7+$26)
        move    b0,x:(r7+$28)
        move    x:(r7+$22),a
        move    x:(r0),x0
        add     x0,a
        move    a,x0
        move    #>$59999a,y0
        mpy     y0,x0,a
        move    x:(r7+$0d),y1
        move    x:(r0),b
        sub     b,a
        asr     a
        move    a,x0
        mpy     x0,y1,a
        asl     a
        add     b,a
        move    a,x:(r0)+
rppend:
        nop     
        rts     
; ---- subroutines (after their callers) ----
rpexp:
        move    a1,b
        asr     #$12,a,a  ; a1 = n = floor(y)
        add     #>$1,a
        move    a1,x1  ; n + 1 (never 0: a do count of 0 is not a skip)
        and     #>$03ffff,b
        asl     #$5,b,b  ; f in Q23, b2 stays 0
        move    b1,x0
        move    #>$2c5c86,y0
        mpy     y0,x0,b
        move    b,y0  ; g = f ln2 / 2
        move    #>$02aaab,x0
        mpy     y0,x0,b
        sub     #>$0aaaab,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$200000,b
        move    b,x0
        mpy     y0,x0,b
        sub     #>$400000,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$400000,b  ; e^-g / 2
        move    b,x0
        mpy     x0,x0,b
        asl     #$2,b,b  ; 2^-f in (0.5, 1]
        do      x1,>rpxpend
        asr     b
rpxpend:
        asl     b
        rts     
